const requester = $json;
if (!requester.id || !requester.active) throw new Error('Invalid session.');

const body = $('Webhook: update-ticket').first().json.body || {};
const id = parseInt(body.id, 10);
if (!Number.isInteger(id)) throw new Error('"id" is required.');

const VALID_STATUSES = ['open', 'pending', 'resolved', 'closed'];
const VALID_PRIORITIES = ['low', 'normal', 'high', 'urgent'];
if (body.status !== undefined && !VALID_STATUSES.includes(body.status)) throw new Error('Invalid status.');
if (body.priority !== undefined && !VALID_PRIORITIES.includes(body.priority)) throw new Error('Invalid priority.');

const resolving = body.status === 'resolved' || body.status === 'closed';

return [{
  json: {
    id,
    subject: body.subject !== undefined ? body.subject : null,
    description: body.description !== undefined ? body.description : null,
    status: body.status !== undefined ? body.status : null,
    priority: body.priority !== undefined ? body.priority : null,
    category: body.category !== undefined ? (body.category || null) : null,
    contactId: body.contact_id !== undefined ? (body.contact_id || null) : null,
    accountId: body.account_id !== undefined ? (body.account_id || null) : null,
    assignedUser: body.assigned_user !== undefined ? (body.assigned_user || null) : null,
    resolutionNotes: body.resolution_notes !== undefined ? (body.resolution_notes || null) : null,
    resolvedAt: resolving ? new Date().toISOString() : null,
    resolvedBy: resolving ? requester.id : null,
    requesterId: requester.id,
    requesterName: requester.name,
  },
}];

